import{_ as e,o as r,c as a,a2 as i}from"./chunks/framework.CWgsre3x.js";const f=JSON.parse('{"title":"Terminology glossary","description":"","frontmatter":{},"headers":[],"relativePath":"help/glossary.md","filePath":"help/glossary.md"}'),d={name:"help/glossary.md"};function o(n,t,s,c,l,p){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="terminology-glossary" tabindex="-1">Terminology glossary <a class="header-anchor" href="#terminology-glossary" aria-label="Permalink to &quot;Terminology glossary&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>Reference v0.7.26, not a live installation audit or commercial activation approval. Confirm installed version, permissions, configuration and acceptance.</p></div><p>Terms describe their operational meaning in this documentation, not legal or accounting definitions.</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Tenant</td><td>The company-scoped data and authorization boundary.</td></tr><tr><td>Market / operating hub</td><td>A configured service area with its own operational settings.</td></tr><tr><td>Location catalog</td><td>Approved pickup and drop-off reference locations.</td></tr><tr><td>Booking channel</td><td>A configured origin of booking traffic; active status is not public intake authorization.</td></tr><tr><td>Reservation</td><td>Stored service request and lifecycle record, not necessarily paid or dispatched.</td></tr><tr><td>Quotation</td><td>Price proposal subject to applicable rules and review.</td></tr><tr><td>Server-verified tariff</td><td>A fare verified by authoritative backend rules; missing verification requires review.</td></tr><tr><td>Manual quotation</td><td>Operator-reviewed price when a verified automatic fare is unavailable.</td></tr><tr><td>Journey leg</td><td>Independent outbound or return transport segment.</td></tr><tr><td>Dispatch</td><td>Authorized allocation of operational resources to a reservation or leg.</td></tr><tr><td>Dispatch buffer</td><td>Configured time margin used in operational planning; not a guarantee of availability.</td></tr><tr><td>Vehicle class</td><td>Service category and capacity/rate reference, distinct from a physical vehicle.</td></tr><tr><td>Driver roster</td><td>Operational driver records; separate from authenticated staff accounts.</td></tr><tr><td>Membership / RBAC</td><td>Company membership and role-based access control that determine permitted operations.</td></tr><tr><td>GPS sharing lease</td><td>Time-limited authorization for explicit chauffeur position sharing.</td></tr><tr><td>Geofence</td><td>A geographic boundary used to evaluate a location relative to a configured area.</td></tr><tr><td>ETA</td><td>Estimated time of arrival, not a confirmed arrival.</td></tr><tr><td>Arrival observation</td><td>Timestamped evidence about a transport service&#39;s arrival status.</td></tr><tr><td>Dispatch advisory</td><td>A proposal requiring review before an operational change.</td></tr><tr><td>CRM</td><td>Customer relationship records and repeat-customer linkage.</td></tr><tr><td>Affiliate</td><td>Commercial partner with an agreed referral or commission arrangement.</td></tr><tr><td>Subcontractor</td><td>External transport supplier assigned to provide a service or leg.</td></tr><tr><td>Supplier payable</td><td>Recorded outstanding amount owed to a supplier, subject to reconciliation.</td></tr><tr><td>Payment authorization</td><td>Provider approval or reservation of funds; not necessarily capture or settlement.</td></tr><tr><td>Cash collection</td><td>Recording cash physically received from the passenger.</td></tr><tr><td>Cash handover</td><td>Separate confirmation of physical custody transfer to the office.</td></tr><tr><td>Reconciliation</td><td>Matching recorded financial transactions against verified evidence.</td></tr><tr><td>PSP</td><td>Payment service provider; integration readiness does not mean activation.</td></tr><tr><td>Webhook</td><td>Provider callback to an application endpoint; verify authenticity and duplicate handling.</td></tr><tr><td>Idempotency</td><td>Protection against unintended duplicate effects when a request is retried.</td></tr><tr><td>Outbox</td><td>Persistent queue of notification jobs and their processing state.</td></tr><tr><td>Opt-out</td><td>Recorded restriction on sending a notification to a recipient or channel.</td></tr><tr><td>Human takeover</td><td>Escalation of a conversation to an authorized human operator.</td></tr><tr><td>Sandbox</td><td>Controlled test functionality or environment, not evidence of live service.</td></tr><tr><td>Fail-closed</td><td>An operation remains blocked when its required authorization or readiness is missing.</td></tr><tr><td>Migration</td><td>Versioned database schema or data change requiring release-specific review.</td></tr><tr><td>Release acceptance</td><td>Recorded evidence that a specific release and intended workflow meet agreed checks.</td></tr><tr><td>RPO / RTO</td><td>Agreed recovery point and recovery time objectives, to be tested rather than assumed.</td></tr></tbody></table>',4)])])}const h=e(d,[["render",o]]);export{f as __pageData,h as default};
